// chrome.storage promise API isn't implemented yet (even though the typescript types are already available)
// wrap the chrome.storage callback API so we can use async/await syntax

import { captureMessage } from "./sentry";

// Exported for testing — override to [0, 0, 0] in tests to avoid real delays.
export const MANAGED_STORAGE_RETRY_DELAYS_MS = [1000, 2000, 4000];

// Why a managed-storage read came back without a usable value. `lastError` is
// a real chrome.storage error. `emptyResult` is the ambiguous Chromium case
// — {} with no lastError — which can mean either "no policy set" OR "policy
// not loaded yet" (W3C WebExtensions CG issue #547,
// https://issues.chromium.org/issues/40169579).
type ManagedStorageRetryReason = "lastError" | "emptyResult";

type ManagedStorageResult<T> =
  | { ok: true; value: T }
  | { ok: false; reason: ManagedStorageRetryReason };

const readManagedStorage = <T>(
  key: string,
): Promise<ManagedStorageResult<T>> => {
  return new Promise((resolve) => {
    try {
      chrome.storage.managed.get(key, (items) => {
        if (chrome.runtime.lastError) {
          resolve({ ok: false, reason: "lastError" });
          return;
        }
        const value = items?.[key] as T | undefined;
        if (value === undefined) {
          resolve({ ok: false, reason: "emptyResult" });
          return;
        }
        resolve({ ok: true, value });
      });
    } catch {
      // chrome.storage.managed itself is unavailable (e.g. non-enterprise browser).
      resolve({ ok: false, reason: "lastError" });
    }
  });
};

const delay = (ms: number): Promise<void> =>
  new Promise((resolve) => {
    setTimeout(resolve, ms);
  });

// Best-effort "is this an admin (force-installed) install?" probe used only
// to gate Sentry logging — never to gate retry behavior. We kick this off at
// module load and never await it on the critical path, so even if
// chrome.management.getSelf hangs (the same class of callback-API init race
// that #547 documents for managed storage) we won't block the welcome-tab
// decision. At log time we just read the resolved-or-not state: if it
// hasn't resolved yet, or resolved to non-admin, we skip the log. The cost
// of a hung getSelf is silently dropping Sentry signal for that one device.
let isAdminInstallResolved: boolean | null = null;
const probeIsAdminInstall = (): void => {
  try {
    chrome.management.getSelf((info) => {
      if (chrome.runtime.lastError) {
        isAdminInstallResolved = false;
        return;
      }
      isAdminInstallResolved = info?.installType === "admin";
    });
  } catch {
    isAdminInstallResolved = false;
  }
};
probeIsAdminInstall();

// Exported only so tests can reset the probe state between cases.
export const __resetAdminInstallProbeForTesting = (
  override: boolean | null,
): void => {
  isAdminInstallResolved = override;
};

// Synchronous, never-throws check. Returns true only if the probe has
// resolved AND the resolved value is "admin". A hung/unresolved probe
// returns false (don't log).
const shouldLogToSentry = (reason: ManagedStorageRetryReason): boolean => {
  // lastError is a real chrome.storage error — always worth a Sentry event,
  // regardless of install type. emptyResult only matters on admin installs;
  // on consumer installs an unset policy key is the expected steady state.
  if (reason === "lastError") return true;
  return isAdminInstallResolved === true;
};

const retryManagedStorage = async <T>(
  key: string,
  defaultValue: T,
  remainingDelays: number[],
  attemptNumber: number,
  initialReason: ManagedStorageRetryReason,
): Promise<T> => {
  if (remainingDelays.length === 0) {
    if (shouldLogToSentry(initialReason)) {
      captureMessage(
        "getManagedValue: managed storage unavailable after all retries, using default",
        {
          level: "warning",
          extra: {
            key,
            defaultValue,
            reason: initialReason,
            attempts: MANAGED_STORAGE_RETRY_DELAYS_MS.length + 1,
          },
        },
      );
    }
    return defaultValue;
  }

  const [delayMs, ...rest] = remainingDelays;

  if (shouldLogToSentry(initialReason)) {
    captureMessage("getManagedValue: managed storage unavailable, retrying", {
      level: "warning",
      extra: { key, attempt: attemptNumber, delayMs, reason: initialReason },
    });
  }

  await delay(delayMs);
  const result = await readManagedStorage<T>(key);
  if (result.ok) {
    return result.value;
  }
  return retryManagedStorage(
    key,
    defaultValue,
    rest,
    attemptNumber + 1,
    result.reason,
  );
};

/**
 * Get a value from chrome.storage.managed (enterprise policy storage).
 * Returns defaultValue if no policy is set or if managed storage is unavailable.
 *
 * On freshly provisioned ADE / GPO / VDI / MDM devices, Chrome's managed
 * storage engine can initialize after the extension's onInstalled event fires.
 * We retry up to 3 times with exponential backoff (1s/2s/4s, ~7s total) on
 * both chrome.runtime.lastError AND empty/undefined results, because Chromium
 * cannot distinguish "no policy set" from "policy not loaded yet" — both
 * return {} with no lastError (W3C WebExtensions CG issue #547).
 *
 * Sentry logging is gated by reason to keep consumer installs quiet:
 *   - reason="lastError" → always logged (real chrome.storage error).
 *   - reason="emptyResult" → only logged when chrome.management.getSelf has
 *     reported installType === "admin" (force-installed). The probe runs
 *     once at module load and is never awaited on the critical path, so a
 *     hung getSelf cannot stall the retry behavior — it just silently drops
 *     Sentry signal for that one device.
 */
export const getManagedValue = async <T>(
  key: string,
  defaultValue: T,
): Promise<T> => {
  const firstResult = await readManagedStorage<T>(key);
  if (firstResult.ok) {
    return firstResult.value;
  }

  return retryManagedStorage(
    key,
    defaultValue,
    MANAGED_STORAGE_RETRY_DELAYS_MS,
    1,
    firstResult.reason,
  );
};

export const getSuppressWelcomeTab = async (): Promise<boolean> => {
  return getManagedValue<boolean>("suppressWelcomeTab", false);
};

export const getValue = async <T>(key: string, defaultValue: T): Promise<T> => {
  return new Promise((resolve, reject) => {
    try {
      chrome.storage.sync.get(key, (items) => {
        resolve((items?.[key] as T) ?? defaultValue);
      });
    } catch (e) {
      reject(e);
    }
  });
};

export const setValue = async (key: string, value: any): Promise<void> => {
  return new Promise((resolve, reject) => {
    try {
      chrome.storage.sync.set({ [key]: value }, () => {
        resolve();
      });
    } catch (e) {
      reject(e);
    }
  });
};

export const getUrlPrefix = async (): Promise<string> => {
  return getValue<string>(
    "urlPrefix",
    process.env.URL_PREFIX ?? "https://app.brighthire.ai",
  );
};

export const setUrlPrefix = async (urlPrefix: string): Promise<void> => {
  return setValue("urlPrefix", urlPrefix);
};

export const getCurrentUser = async (): Promise<CurrentUser | null> => {
  return getValue<CurrentUser | null>("currentUser", null);
};

export const setCurrentUser = async (
  currentUser: CurrentUser | null,
): Promise<void> => {
  return setValue("currentUser", currentUser);
};

export const getCurrentUserLastFetch = async (): Promise<number> => {
  return getValue<number>("currentUserLastFetch", 0);
};

export const setCurrentUserLastFetch = async (
  currentUserLastFetch: number,
): Promise<void> => {
  return setValue("currentUserLastFetch", currentUserLastFetch);
};

export const getSuppressScorecardFeedback = async (): Promise<boolean> => {
  return getValue<boolean>("suppressScorecardFeedback", false);
};

export const setSuppressScorecardFeedback = async (
  suppress: boolean,
): Promise<void> => {
  return setValue("suppressScorecardFeedback", suppress);
};
