import { BRIGHTHIRE_ID } from "../../utils/calendarButton";
import {
  closeDrawerToast,
  openDrawerToast,
  setupDrawer,
} from "../../utils/drawer";
import { MutationSummary } from "../../utils/MutationSummary";
import {
  addPassiveMessageListener,
  sendMessageWithTabId,
} from "../../utils/message";
import { onDocumentLoaded } from "../../utils/onDocumentLoaded";
import { isAtsCallButtonHidden } from "../../utils/orgSettings";
import { emailRegex, phoneNumberRegex } from "../../utils/regex";
import { initSentry } from "../../utils/sentry";
import { buildUrl } from "../../utils/url";
import { BUTTON_STYLE } from "../style";

initSentry();

interface CandidateInfo {
  email?: string;
  phone?: string;
  intent: string;
}

const getWorkdayFeedbackFormElements = (): Element[] => {
  const selectorList = [
    '[title="Job Application Details"]',
    '[title="Interview Feedback"]',
    '[title="Manage Interview Feedback"]',
  ];
  return selectorList.flatMap((s) => Array.from(document.querySelectorAll(s)));
};

const getWorkdayCandidateElements = (): string[] => {
  const selectorList = [
    '[data-automation-id="EMAIL_charm"]',
    ".WI1W.WB1W.WP-W",
    '[data-automation-id="profileHeaderItemTitle"]',
    '[data-automation-id="workerProfileSummaryHeaderCardContent"]',
  ];

  let elements = Array.from(document.querySelectorAll(selectorList[0]))
    .map((e) => e.innerHTML)
    .filter(Boolean);
  if (elements.length) {
    return elements;
  }

  elements = Array.from(document.querySelectorAll(selectorList[1]))
    .map((e) => e.parentElement?.innerHTML ?? "")
    .filter(Boolean);
  if (elements.length) {
    return elements;
  }

  elements = Array.from(document.querySelectorAll(selectorList[2]))
    .map((e) => e.parentElement?.innerHTML ?? "")
    .filter(Boolean);
  if (elements.length) {
    return elements;
  }

  elements = Array.from(document.querySelectorAll(selectorList[3]))
    .map((e) => e.innerHTML ?? "")
    .filter(Boolean);
  if (elements.length) {
    return elements;
  }

  return [];
};

const sessionStorageKey = (): string => {
  return `brightHire-${window.location.pathname.replace(".htmld", "")}`;
};

const getWorkdayCandidateSessionStorage = (): {
  email: string;
  phone: string;
} => {
  const key = sessionStorageKey();
  const email = sessionStorage.getItem(`${key}-workdayEmail`) || "";
  const phone = sessionStorage.getItem(`${key}-workdayPhone`) || "";
  return { email, phone };
};

const setWorkdayCandidateSessionStorage = (
  email: string,
  phone: string,
): void => {
  const key = sessionStorageKey();
  sessionStorage.setItem(`${key}-workdayEmail`, email);
  sessionStorage.setItem(`${key}-workdayPhone`, phone);
};

const clearWorkdaySessionStorage = (): void => {
  const storageKey = sessionStorageKey();
  const keys = Array.from(
    { length: sessionStorage.length },
    (_, i) => sessionStorage.key(i) ?? "",
  ).filter((key) => key.startsWith(storageKey));

  keys.forEach((key) => {
    sessionStorage.removeItem(key);
  });
};

const hasWorkdayCandidateInfo = (): boolean => {
  const { email, phone } = getWorkdayCandidateSessionStorage();
  if (email || phone) return true;

  return (
    getWorkdayCandidateElements().length > 0 ||
    getWorkdayFeedbackFormElements().length > 0
  );
};

const getOrScrapeWorkdayCandidateInfo = (): CandidateInfo | null => {
  let { email, phone } = getWorkdayCandidateSessionStorage();

  if (email || phone)
    return {
      intent: "Candidate",
      ...(!!email && { email }),
      ...(!!phone && { phone }),
    };

  const candidateElements = getWorkdayCandidateElements();
  const feedbackFormElements = getWorkdayFeedbackFormElements();
  if (candidateElements.length === 0 && feedbackFormElements.length === 0)
    return null;

  candidateElements.some((e) => {
    if (!email) {
      const emailMatch = emailRegex.exec(e)?.[0];
      if (emailMatch) email = emailMatch;
    }
    if (!phone) {
      const phoneMatch = phoneNumberRegex.exec(e)?.[0];
      if (phoneMatch) {
        // match phone from regex, and remove non numerics
        phone = phoneMatch.replace(/[^0-9.]+/g, "");
      }
    }

    return !!(email && phone);
  });

  setWorkdayCandidateSessionStorage(email, phone);

  return {
    intent: "Candidate",
    ...(!!email && { email }),
    ...(!!phone && { phone }),
  };
};

const observer = new MutationSummary({
  callback: () => {
    if (!document.querySelector('[data-automation-id="workerProfile"]')) {
      return;
    }
    checkPage();
  },
  queries: [
    { element: '[data-automation-id="workerProfile"]' }, // This is for checking the candidate page from the "inbox"
  ],
});
observer.disconnect();

/**
 * Returns true if the page matches `www.workday.com/:locale-code/*`,
 * where `:locale-code` is like "en-us" (for example)
 */
const isMarketingPage = (): boolean => {
  const { hostname, pathname } = window.location;
  if (hostname !== "www.workday.com") return false;

  try {
    const firstPathPart = pathname.split("/")[1];
    return !!new Intl.Locale(firstPathPart);
  } catch (_e) {
    return false;
  }
};

const shouldShow = (): boolean => {
  if (isMarketingPage()) return false;
  // We have seen in SSO-enabled workday instances that they first land on a page
  // like `/<customer name>/login-saml.flex`. We don't want to run on that page
  // because it seems to block the proper redirects
  if (window.location.pathname.match(/\.flex$/)) return false;
  return true;
};

const cleanUpButtons = (baseNode?: HTMLElement | null): void => {
  const existingButtons = (baseNode || document)?.querySelectorAll(
    `.brightHireButtonContainer`,
  );
  existingButtons?.forEach((button) => {
    button.remove();
  });
};

const buildBrightHireButton = async (
  info: CandidateInfo,
): Promise<HTMLButtonElement> => {
  const brighthireButton = document.createElement("button");
  brighthireButton.id = BRIGHTHIRE_ID;
  brighthireButton.type = "button";
  brighthireButton.setAttribute("style", BUTTON_STYLE);
  brighthireButton.style.height = "34px";
  brighthireButton.style.paddingLeft = "8px";
  brighthireButton.style.paddingRight = "8px";
  brighthireButton.style.margin = "auto 0";
  brighthireButton.innerText = "Call with BrightHire";
  const url = await buildUrl(
    "/interview-assistant/integrations/workdayCandidate",
    {
      url: window.location.href,
      phoneNumber: info.phone || "",
      email: info.email || "",
    },
  );
  brighthireButton.onclick = () =>
    chrome.runtime.sendMessage({
      action: "openIA",
      payload: { url, windowAvailHeight: window.screen.availHeight },
    });
  return brighthireButton;
};

const setupCallButton = async (info: CandidateInfo): Promise<void> => {
  if (await isAtsCallButtonHidden()) return;
  const brightHireButton = await buildBrightHireButton(info);
  const profileContainer = document.querySelector<HTMLDivElement>(
    '[data-automation-id="workerProfileSummaryHeaderCardContent"]',
  );
  const buttonContainer = document.createElement("div");
  buttonContainer.className = "brightHireButtonContainer";
  buttonContainer.style.width = "100%";
  buttonContainer.style.padding = "8px 0";
  buttonContainer.appendChild(brightHireButton);
  cleanUpButtons();
  profileContainer?.insertBefore(buttonContainer, profileContainer.firstChild);
};

const checkPage = async (retries = 0): Promise<void> => {
  if (!shouldShow()) {
    observer.disconnect();
    closeDrawerToast();
    return;
  }

  /** Retry for up to 15 seconds until DOM elements are available */
  if (retries < 50 && !hasWorkdayCandidateInfo()) {
    setTimeout(() => checkPage(retries + 1), 300);
    return;
  }

  observer.reconnect();
  const candidateInfo = getOrScrapeWorkdayCandidateInfo();
  const reloadTriggered = await setupDrawer({
    forceReload: true,
    urlParams: {
      ...candidateInfo,
    },
  });
  if (reloadTriggered) {
    sendMessageWithTabId({ action: "drawerLoading" });
  }
  openDrawerToast();
};

onDocumentLoaded(checkPage);

addPassiveMessageListener(async ({ message }) => {
  if (message.action === "tabUrlChanged") {
    clearWorkdaySessionStorage();
    // Always signal that drawer may be loading on URL change
    sendMessageWithTabId({ action: "drawerLoading" });
    checkPage();
  }
  if (message.action === "loadingComplete") {
    const candidateInfo = getOrScrapeWorkdayCandidateInfo();
    if (candidateInfo?.phone) {
      await setupCallButton(candidateInfo);
    }
  }
});
