import { downCarrot } from "./icon";

const ICON_SRC =
  "data:image/png;base64,";

export const BRIGHTHIRE_ID = "brighthire_btn";

type CalendarButtonContainerParams = {
  /** The primary button element to launch an interview */
  brighthireButton: HTMLElement;
  /** Whether to add a dropdown for starting as in-person */
  inPersonAllowed: boolean;
  /** Callback for when the in-person option is clicked */
  onInPersonClicked: (e: PointerEvent) => void;
  /** Callback for when the in-person option is cleared */
  onInPersonCleared: (e: PointerEvent) => void;
  /** The gap between the BH icon and the button */
  gap?: string;
  /** The margin around the container */
  margin?: string;
};

export const buildCalendarButtonContainer = ({
  brighthireButton,
  inPersonAllowed,
  onInPersonClicked,
  onInPersonCleared,
  gap,
  margin,
}: CalendarButtonContainerParams): HTMLDivElement => {
  const bhIcon = document.createElement("img");
  bhIcon.src = ICON_SRC;
  bhIcon.alt = "BH";
  bhIcon.id = "bh-icon";
  if (gap) bhIcon.style.setProperty("margin-right", gap);

  const container = document.createElement("div");
  container.id = BRIGHTHIRE_ID;
  if (margin) container.style.setProperty("margin", margin);

  const rightCol = document.createElement("div");
  rightCol.appendChild(brighthireButton);

  if (inPersonAllowed) {
    brighthireButton.classList.add("tooltip");
    const inPersonButton = buildTooltipButton({
      onInPersonClicked,
      onInPersonCleared,
    });
    inPersonButton.style.setProperty("padding", "8px 6px");
    rightCol.appendChild(inPersonButton);
  }

  container.appendChild(bhIcon);
  container.appendChild(rightCol);

  brighthireButton.setAttribute("id", "call-with-bh");
  brighthireButton.classList.add("bh-btn");
  brighthireButton.style.setProperty("padding", "8px 15px");

  return container;
};

const buildTooltipButton = ({
  onInPersonClicked,
  onInPersonCleared,
}: Pick<
  CalendarButtonContainerParams,
  "onInPersonCleared" | "onInPersonClicked"
>): HTMLElement => {
  const inPersonButton = document.createElement("a");
  inPersonButton.id = "in-person-bh";
  inPersonButton.classList.add("bh-btn");

  const icon = downCarrot();
  inPersonButton.appendChild(icon);

  const tooltip = document.createElement("div");
  tooltip.id = "in-person-tooltip";
  tooltip.textContent = "Start as in-person interview";
  inPersonButton.appendChild(tooltip);

  let tooltipShowing = false;
  inPersonButton.onclick = () => {
    if (tooltipShowing) return;
    tooltip.style.setProperty("display", "block");
    tooltipShowing = true;
    const onClose = (e: PointerEvent): void => {
      if (e.target === tooltip) {
        onInPersonClicked(e);
      }
      requestAnimationFrame(() => {
        tooltip.style.setProperty("display", "none");
        tooltipShowing = false;
        onInPersonCleared(e);
      });
    };
    requestAnimationFrame(() => {
      document.addEventListener("click", onClose, {
        once: true,
        capture: true,
      });
    });
  };

  return inPersonButton;
};
